def transform(grid):
    from collections import Counter

    # Find separator rows (rows where all cells have the same separator value)
    # For delimiter detection, look for rows that are uniform and different from data sections
    sep_rows = []
    for i in range(len(grid)):
        if all(grid[i][j] == grid[i][0] for j in range(len(grid[0]))):
            # Check if this uniform row is different from top data row
            is_different = grid[0][0] != grid[i][0]
            if is_different:
                sep_rows.append(i)

    # Find separator columns similarly
    sep_cols = []
    for j in range(len(grid[0])):
        if all(grid[i][j] == grid[0][j] for i in range(len(grid))):
            # Check if this uniform column is different from left data column
            is_different = grid[0][0] != grid[0][j]
            if is_different:
                sep_cols.append(j)

    # Build row sections (excluding separators)
    row_sections = []
    in_data_row = True
    for r in range(len(grid)):
        if in_data_row and r not in sep_rows:
            pass
        if sep_rows and r in sep_rows:
            if len(row_sections) == 0:
                row_sections.append((0, r))
            else:
                prev_end = row_sections[-1][1]
                row_sections.append((prev_end + 1, r))
            in_data_row = False
        elif not sep_rows or (isinstance(in_data_row, bool) and in_data_row):
            if len(row_sections) == 0:
                if all(c != 1 for c in grid[r]):
                    row_sections.append((0, r))

    # Build column sections (excluding separators)
    col_sections = []
    if not sep_cols:
        col_sections.append((0, len(grid[0])))
    else:
        start = 0
        for end in sep_cols:
            col_sections.append((start, end))
            start = end + 1
        col_sections.append((start, len(grid[0])))

    # For Demo 2, leftmost column section gets minority fill in its data rows
    # Apply to the first non-separator section
    if not row_sections:
        # No data rows, return grid unchanged
        return [row[:] for row in grid]

    top_r_start, top_r_end = row_sections[0]
    if col_sections:
        first_c_start, first_c_end = col_sections[0]

        # Collect values from first column section in top section
        values = []
        for r in range(top_r_start, top_r_end):
            for c in range(first_c_start, first_c_end):
                values.append(grid[r][c])

        # Determine fill value (minority value)
        if values:
            counts = Counter({x: 0 for x in range(10)})
            for v in values:
                if 0 <= v <= 9:
                    counts[v] += 1
            fill = min(counts.items(), key=lambda x: x[1])[0] if counts else 9
        else:
            fill = 9

        # Fill the section
        for r in range(top_r_start, top_r_end):
            for c in range(first_c_start, first_c_end):
                grid[r][c] = fill

    return [row[:] for row in grid]
